# Demo sign-ins for local development. A second center with its own director makes tenancy visible:
# signing in as either director shows only that director's center.
#
# Locally the password is a fictional demo value, not a secret. A deployed demo sets DEMO_PASSWORD
# (generated by Terraform) instead of the public one.
password = Rails.env.production? ? ENV.fetch("DEMO_PASSWORD") : ENV.fetch("DEMO_PASSWORD", "littleoaks-demo")

little_oaks = Center.find_by!(name: "Little Oaks Early Learning")
birchwood = Center.find_or_create_by!(name: "Birchwood Kids Club") do |c|
  c.city = "St. Paul"
  c.timezone = "America/Chicago"
  c.director_name = "Marcus Lindqvist"
end
birchwood.classrooms.find_or_create_by!(name: "Robins") do |r|
  r.age_min_months = 33
  r.age_max_months = 60
  r.capacity = 12
  r.ratio = 10
end

[
  [ "Renee Albright", "renee@littleoaks.test", little_oaks ],
  [ "Marcus Lindqvist", "marcus@birchwood.test", birchwood ]
].each do |name, email, center|
  user = User.find_or_create_by!(email_address: email) do |u|
    u.name = name
    u.password = password
  end
  user.memberships.find_or_create_by!(center: center)
end

puts "Demo directors: renee@littleoaks.test (Little Oaks), marcus@birchwood.test (Birchwood)."

# A demo parent for the mobile app: a Little Oaks family with an enrolled child, attendance, and a
# past-due invoice, so a director approving that family's tuition nudge shows up in the parent's inbox.
family = little_oaks.families
                    .where(id: Invoice.past_due(little_oaks.today).select(:family_id))
                    .where(id: Child.joins(:enrollments).merge(Enrollment.where(status: "enrolled")).select(:family_id))
                    .order(:id).first!
parent = User.find_or_create_by!(email_address: "parent@littleoaks.test") do |u|
  u.name = family.primary_guardian_name
  u.password = password
end
parent.guardianships.find_or_create_by!(family: family)
family.messages.find_or_create_by!(proposed_action_id: nil, subject: "Welcome to Cubby") do |m|
  m.center = little_oaks
  m.body = "Hi #{family.guardian_first_name}, this is where Little Oaks will send updates about your family. " \
           "You can also see check-in times and tuition here. - #{little_oaks.director_name}"
  m.sent_at = Time.current
end

puts "Demo parent: parent@littleoaks.test (#{family.name})."
